package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTlDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("Proteksyon mula sa Lahat ng Kapinsalaan", "Sa ngalan ni Allah, na ang Kanyang pangalan ay walang anumang bagay sa lupa o sa langit ay maaaring magdulot ng pinsala, at Siya ang Ganap na Nakaririnig, ang Nakaaalam ng Lahat.", "Tatlong beses tuwing umaga at gabi.", "Ang sinumang magsabi nito ng tatlong beses sa umaga at gabi, walang makapipinsala sa kanya."),
        "dua_raditu_billahi" to DuaText("Kasiyahan sa Allah bilang Panginoon", "Ako ay nalulugod kay Allah bilang aking Panginoon, sa Islam bilang aking relihiyon at kay Muhammad ﷺ bilang aking Propeta.", "Tatlong beses umaga at gabi.", "Nagiging karapatan ni Allah na bigyan siya ng kasiyahan sa Araw ng Paghuhukom."),
        "dua_hasbiyallah" to DuaText("Hasbiyallah (Sapat na ang Allah)", "Ang Allah ay sapat na sa akin; walang diyos maliban sa Kanya. Sa Kanya ako nagtitiwala, at Siya ang Panginoon ng Makapangyarihang Trono.", "Pitong beses umaga at gabi.", "Isang talata ng Quran; Sapat na si Allah laban sa mga alalahanin sa mundo at sa Kabilang Buhay."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("SubhanAllahi wa bihamdihi", "Luwalhati kay Allah at ang lahat ng papuri ay sa Kanya.", "Isang daang beses sa isang araw.", "Sinumang magsabi nito ng isang daang beses sa isang araw ay pinatawad ang kanyang mga kasalanan, kahit na ang mga ito ay parang bula ng dagat."),
        "dua_tahleel_100" to DuaText("La ilaha illallahu wahdahu", "Walang sinumang karapat-dapat sambahin maliban kay Allah, nag-iisa, walang katambal. Sa kanya ang kapangyarihan at sa Kanya ang papuri, at Siya ang may kapangyarihan sa lahat ng bagay.", "Malaking birtud sa pagsasabi nito ng isang daang beses sa isang araw.", "Ang gantimpala ng pagpapalaya sa sampung alipin, isang daang mabuting gawa na naisulat, isang daang kasalanan ang nabura, at proteksyon mula kay Shaytan hanggang gabi."),
        "dua_leaving_mosque" to DuaText("Pag-alis ng Mosque", "O Allah, hinihiling ko sa Iyo ang Iyong kagandahang-loob.", "Paglabas ng mosque gamit ang kaliwang paa.", "Paghingi ng biyaya at panustos ni Allah kapag aalis sa mosque."),
        "dua_after_adhan" to DuaText("Pagkatapos ng Adhan", "O Allah, Panginoon nitong perpektong panawagan at ang panalangin na malapit nang maitatag, ipagkaloob kay Muhammad ﷺ al-Wasilah at kabutihan, at itaas siya sa Pinupuri na Istasyon na Iyong ipinangako sa kanya.", "Matapos makumpleto ang adhan.", "Ang sinumang magsabi nito ay pagkakalooban ng pamamagitan ng Propeta ﷺ sa Araw ng Paghuhukom."),
        "dua_after_salah_istighfar" to DuaText("Pagkatapos ng Fard Salah", "Humihingi ako ng kapatawaran sa Allah (3 beses). O Allah, Ikaw ay as-Salam at mula sa Iyo ang kapayapaan. Mapalad ka, O Nagmamay-ari ng Kamahalan at Karangalan.", "Kaagad pagkatapos ng salam.", "Binibigkas ito ng Propeta ﷺ pagkatapos ng bawat obligadong panalangin."),
        "dua_after_salah_help_dhikr" to DuaText("Tulungan Mo Akong Alalahanin Kita", "O Allah, tulungan Mo akong maalala Ka, magpasalamat sa Iyo at sumamba sa Iyo sa pinakamahusay na paraan.", "Pagkatapos ng bawat panalangin — pinayuhan ng Propeta ﷺ si Mu'adh (RA) na sabihin ito.", "Isang espesyal na payo ng Propeta ﷺ — kahusayan at katatagan sa pagsamba."),
        "dua_sleep_tasbeeh" to DuaText("Tasbeeh-e-Fatimi bago matulog", "Luwalhati sa Allah (33), ang lahat ng papuri ay para sa Allah (33), ang Allah ang Pinakamadakila (34).", "Bago matulog — itinuro ito ng Propeta ﷺ kina Fatimah at Ali (RA).", "Ang Propeta ﷺ ay nagsabi na ito ay mas mabuti para sa iyo kaysa sa isang alipin."),
        "dua_sleep_qina_adhab" to DuaText("Proteksyon mula sa Parusa", "O Allah, protektahan Mo ako mula sa Iyong kaparusahan sa Araw na Iyong buhayin ang Iyong mga lingkod.", "Tatlong beses, nakalagay ang kanang kamay sa ilalim ng pisngi.", "Ginagawang paalala ng kamatayan ang pagtulog at paghahanda para sa Kabilang Buhay."),
        "dua_bad_dream" to DuaText("Pagkatapos ng Masamang Panaginip", "Ako ay nagpapakupkop kay Allah mula sa Shaytan, ang isinumpa.", "Pagkatapos ng masamang panaginip: tuyuin nang bahagya sa kaliwa ng tatlong beses, pagkatapos ay lumiko sa kabilang panig.", "Ang masamang panaginip ay hindi makakasama sa iyo; huwag mong sabihin kahit kanino ang tungkol dito."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Ya Hayyu Ya Qayyum", "O Walang-hanggang Buhay, O Tagapagtaguyod ng lahat! Sa Iyong awa ako ay humihingi ng tulong.", "Kapag ang isang bagay ay naging napakabigat.", "Sa tuwing may bagay na nagpabagabag sa Propeta ﷺ, sasabihin niya ito."),
        "dua_entering_market" to DuaText("Pagpasok sa Marketplace", "Walang sinumang karapat-dapat sambahin maliban kay Allah, nag-iisa, walang katambal. Kanya ang kapangyarihan at sa Kanya ang papuri. Siya ang nagbibigay ng buhay at nagiging sanhi ng kamatayan, at Siya ay Walang-hanggang Buhay at hindi namamatay. Nasa Kanyang kamay ang lahat ng mabuti, at Siya ay may kapangyarihan sa lahat ng bagay.", "Pagpasok sa palengke.", "Ang hadith ay nagbanggit ng malaking gantimpala para dito (isang milyong mabubuting gawa)."),
        "dua_adam_forgiveness" to DuaText("Dua ni Propeta Adam (AS)", "Panginoon namin, kami ay nagkasala sa aming sarili, at kung hindi Mo kami patatawarin at kaawaan kami, kami ay tiyak na kabilang sa mga talunan.", "Ang dua ng pagsisisi nina Adan at Hawwa (AS).", "Ang unang pagsisisi ng sangkatauhan - tinanggap ito ni Allah."),
        "dua_abu_bakr" to DuaText("Nagturo si Dua kay Abu Bakr (RA)", "O Allah, ako ay lubos na nagkasala sa aking sarili, at walang nagpapatawad sa mga kasalanan maliban sa Iyo, kaya't bigyan mo ako ng kapatawaran mula sa Iyo at maawa ka sa akin. Katotohanan, Ikaw ang Mapagpatawad, ang Maawain.", "Itinuro ng Propeta ﷺ ito kay Abu Bakr as-Siddiq (RA) na magsabi sa panalangin (pagkatapos ng tashahhud).", "Isang Sunnah dua para sa pagtatapos ng panalangin."),
        "dua_astaghfirullah_atubu" to DuaText("Araw-araw na Istighfar", "Ako ay humihingi ng kapatawaran sa Allah at ako ay bumaling sa Kanya sa pagsisisi.", "Ang Propeta ﷺ ay humingi ng kapatawaran ng higit sa pitumpung beses sa isang araw.", "Ang Propeta ﷺ ay nagsabi: Ako ay humihingi ng kapatawaran sa Allah at nagsisisi sa Kanya ng higit sa pitumpung beses sa isang araw."),
        "dua_laylatul_qadr" to DuaText("Dua para sa Laylat al-Qadr", "O Allah, Ikaw ang Pinakamapagpatawad at mahilig kang magpatawad, kaya patawarin mo ako.", "Itinuro kay Aisha (RA) para sa Laylat al-Qadr.", "Isang espesyal na dua para sa mga huling gabi ng Ramadan at Laylat al-Qadr."),
        "dua_family_coolness" to DuaText("Lamig ng Mata (Asawa at Mga Anak)", "Panginoon namin, ipagkaloob mo sa amin mula sa aming mga asawa at sa aming mga supling ang lamig ng aming mga mata, at gawin kaming mga pinuno ng mga matuwid.", "Isang Quranic na dua para sa isang matuwid na asawa at mga anak.", "Para sa kapayapaan sa tahanan at matuwid na mga anak."),
        "dua_righteous_children" to DuaText("Para sa Matuwid na Anak", "Panginoon ko, bigyan mo ako ng dalisay na supling mula sa Iyong sarili. Katotohanan, Ikaw ang Dumirinig ng pagsusumamo.", "Ang dua ni Propeta Zakariyya (AS).", "Isang Quranic na dua para sa mga naghahanap ng mga bata."),
        "dua_ibrahim_prayer_family" to DuaText("Mga Tagapagtatag ng Panalangin", "Panginoon ko, gawin mo akong tagapagtatag ng panalangin, at mula sa aking mga inapo. Panginoon, tanggapin mo ang aking pagsusumamo. Panginoon namin, patawarin mo ako, ang aking mga magulang at ang mga mananampalataya sa Araw ng pagtatatag ng account.", "Ang dua ni Propeta Ibrahim (AS) para sa kanyang sarili at sa kanyang mga inapo.", "Karaniwang binibigkas sa pagtatapos ng panalangin."),
        "dua_newlywed" to DuaText("Binabati ang Bagong Kasal", "Pagpalain ka nawa ng Allah, magpadala ng mga pagpapala sa iyo at pagsamahin kayong dalawa sa kabutihan.", "Kapag binabati ang isang tao sa kanilang kasal.", "Ang pagbati sa Sunnah para sa isang kasal."),
        "dua_before_eating" to DuaText("Bago Kumain", "Sa ngalan ni Allah. (Kung nakalimutan:) Sa ngalan ng Allah, sa simula at sa wakas nito.", "Bago kumain. Kung nakalimutan mo, sabihin ito sa kalahati.", "Ang pagsasabi ng Bismillah ay pumipigil kay Shaytan sa pagbabahagi ng pagkain."),
        "dua_after_eating" to DuaText("Pagkatapos Kumain", "Ang lahat ng papuri ay para sa Allah na nagpakain sa akin nito at naglaan nito para sa akin nang walang anumang lakas o kapangyarihan sa aking bahagi.", "Nang matapos ang pagkain.", "Ang mga nakaraang kasalanan ng nagsabi na ito ay pinatawad."),
        "dua_host" to DuaText("Para sa Host", "O Allah, pagpalain Mo sila sa mga ipinagkaloob Mo sa kanila, patawarin mo sila at maawa ka sa kanila.", "Para sa host, pagkatapos kumain sa bahay ng isang tao.", "Nagpapasalamat sa host sa paraang Sunnah."),
        "dua_breaking_fast" to DuaText("Sa Pagsira ng Fast", "Ang uhaw ay nawala, ang mga ugat ay nabasa, at ang gantimpala ay napatunayan, kung niloob ng Allah.", "Sa oras ng iftar.", "Ang Propeta ﷺ ay nagsabi nito nang siya ay nag-aayuno."),
        "dua_new_clothes" to DuaText("Nakasuot ng Bagong Damit", "O Allah, ang lahat ng papuri ay sa Iyo; binihisan mo ako nito. Hinihiling ko sa Iyo ang kabutihan nito at ang kabutihan ng kung ano ito ay ginawa para sa, at ako ay nagpapakupkop sa Iyo mula sa kasamaan nito at ang kasamaan ng kung ano ito ay ginawa para sa.", "Kapag may suot na bagong damit (pangalan ito, tulad ng sando o turban).", "Ginawa ng Propeta ﷺ ang dua na ito kapag may suot na bagong damit. (Ang pang-araw-araw na dua para sa pagbibihis ay nasa ilalim ng 'Pagbibihis'.)"),
        "dua_rabbana_atina" to DuaText("Mabuti sa Mundo at sa Kabilang Buhay", "Aming Panginoon, bigyan mo kami ng kabutihan sa mundong ito at kabutihan sa Kabilang-Buhay, at protektahan mo kami mula sa kaparusahan ng Apoy.", "Ang dalawang ang Propeta ﷺ ay madalas na ginawa.", "Isang du'a na nagtitipon ng bawat kabutihan sa mundo at sa Kabilang Buhay."),
        "dua_rabbi_zidni_ilma" to DuaText("Pagtaas ng Kaalaman", "Panginoon ko, dagdagan mo ako ng kaalaman.", "Para sa pagtaas ng kaalaman.", "Si Allah ay nag-utos sa Propeta ﷺ na humingi ng dagdag sa walang anuman kundi kaalaman."),
        "dua_musa_sharh_sadr" to DuaText("Pagbukas ng Dibdib (Musa AS)", "Panginoon, palawakin mo ang aking dibdib para sa akin, pagaanin mo ang aking gawain para sa akin, at alisin mo ang tali sa aking dila upang maunawaan nila ang aking pananalita.", "Bago ang pagsusulit, isang talumpati o anumang mahirap na gawain.", "Ang dua ni Propeta Musa (AS) — kalmado ng puso at kadalian sa gawain ng isang tao."),
        "dua_la_tuzigh" to DuaText("Katatagan ng Puso", "Panginoon namin, huwag mong hayaang lumihis ang aming mga puso pagkatapos Mo kaming gabayan, at bigyan mo kami ng awa mula sa Iyong sarili. Tunay, Ikaw ang Tagapagbigay.", "Para sa katatagan sa patnubay.", "Isang panalangin para sa pananatiling matatag sa pananampalataya."),
        "dua_ya_muqallib" to DuaText("O Tagapagpaikot ng mga Puso", "O Tagapagbalik ng mga puso, panatilihing matatag ang aking puso sa Iyong relihiyon.", "Ang Propeta ﷺ ay madalas na gumawa ng dalawang ito.", "Ayon kay Umm Salamah (RA), ang dalawang ang Propeta ﷺ ay madalas na ginawa."),
        "dua_la_tuakhidhna" to DuaText("Mga Huling Talata ng Surah Al-Baqarah", "Panginoon, huwag mo kaming ipagtanggol kung kami ay nakakalimutan o nagkamali. Panginoon namin, huwag Mo kaming lagyan ng pasanin gaya ng ipinadala Mo sa mga nauna sa amin. Panginoon namin, huwag mo kaming pabigatan ng hindi namin kayang tiisin. Patawarin mo kami, patawarin mo kami at maawa ka sa amin. Ikaw ang aming Tagapagtanggol, kaya tulungan mo kami laban sa mga taong hindi naniniwala.", "Sa gabi bago matulog — ang huling dalawang talata ng Surah al-Baqarah.", "Sinuman ang bumigkas ng huling dalawang talata ng Surah al-Baqarah sa gabi, sila ay magiging sapat sa kanya."),
        "dua_visiting_sick" to DuaText("Pagbisita sa Maysakit", "Hinihiling ko kay Allah ang Makapangyarihan, Panginoon ng Makapangyarihang Trono, na pagalingin ka.", "Pitong beses kapag bumibisita sa maysakit.", "Kung hindi pa dumating ang oras ng kamatayan, pagagalingin siya ni Allah."),
        "dua_ruqyah_pain" to DuaText("Para sa Sakit sa Katawan", "Ako ay nagpapakupkop kay Allah at sa Kanyang kapangyarihan mula sa kasamaan ng aking nararamdaman at kung ano ang aking kinakatakutan.", "Ilagay ang iyong kamay kung saan ito masakit, sabihin ang Bismillah ng tatlong beses, pagkatapos ang dalawang ito ay pitong beses.", "Itinuro ito ng Propeta ﷺ kay Uthman ibn Abil-'As (RA) para sa sakit."),
        "dua_ruqyah_nabawi" to DuaText("Propetikong Ruqyah para sa Maysakit", "O Allah, Panginoon ng sangkatauhan! Alisin ang pinsala at bigyan ng lunas, sapagka't Ikaw ang Nagpapagaling; walang lunas maliban sa Iyong lunas — isang lunas na walang karamdamang iniiwan.", "Habang ipinapasa ang kamay sa maysakit.", "Binibigkas ito ng Propeta ﷺ nang bumisita sa mga maysakit na miyembro ng kanyang pamilya."),
        "dua_kalimat_tammat" to DuaText("Paghahanap ng Kanlungan sa Perpektong Salita", "Ako ay nagpapakupkop sa perpektong salita ni Allah mula sa kasamaan ng Kanyang nilikha.", "Kapag humihinto sa isang lugar, o sa gabi.", "Ang sinumang tumigil sa isang lugar at magsabi nito, walang makakasama sa kanya hanggang sa umalis siya dito."),
        "dua_evil_eye" to DuaText("Proteksyon para sa mga Bata (Evil Eye)", "Humihingi ako ng proteksyon para sa inyo pareho sa perpektong mga salita ng Allah mula sa bawat demonyo at bawat makamandag na nilalang, at mula sa bawat mapaminsalang mata.", "Binibigkas ito ng Propeta ﷺ kay Hasan at Husain (RA).", "Isang Sunnah dua upang protektahan ang mga bata mula sa masamang mata at pinsala (para sa isang bata ay magsabi ng 'U'īdhuka')."),
        "dua_seeing_afflicted" to DuaText("Nakikita ang Isang Tao sa Pagsubok", "Ang lahat ng papuri ay para sa Allah na nagligtas sa akin mula sa kung ano ang Kanyang sinubok sa iyo, at pinaboran ako sa karamihan ng Kanyang nilikha.", "Sa pagkakita ng isang tao sa pagsubok (sabihin ito nang tahimik sa iyong sarili).", "Ang nagsasabi na ito ay pinananatiling ligtas mula sa pagsubok na iyon."),
        "dua_istikhara" to DuaText("Salat al-Istikhara", "O Allah, hinahanap ko ang kabutihan sa pamamagitan ng Iyong kaalaman, hinahanap ko ang kakayahan sa pamamagitan ng Iyong kapangyarihan, at hinihiling ko sa Iyo ang Iyong dakilang biyaya. Ikaw ay may kapangyarihan at ako ay wala; Alam Mo at hindi ko alam, at Ikaw ang Nakaaalam ng hindi nakikita. O Allah, kung sa Iyong kaalaman ang bagay na ito (isaalang-alang ito) ay mabuti para sa aking relihiyon, sa aking buhay at sa aking wakas, pagkatapos ay itakda mo ito para sa akin, gawin itong madali para sa akin at pagpalain ako dito. At kung sa Iyong kaalaman ang bagay na ito ay masama para sa aking relihiyon, sa aking buhay at sa aking wakas, pagkatapos ay talikuran ito sa akin at talikuran ako mula rito, at itakda para sa akin ang kabutihan saanman ito naroroon, pagkatapos ay gawing kontento ako dito.", "Pagkatapos ng dalawang rak'ah ng kusang pagdarasal, upang hanapin kung ano ang pinakamabuti sa isang pinahihintulutang bagay.", "Itinuro ng Propeta ﷺ ang mga Kasamahan ng istikhara sa lahat ng bagay habang itinuro niya sa kanila ang isang surah ng Quran."),
    )
}
